create table if not exists public.profiles ( id uuid primary key references auth.users(id) on delete cascade, name text not null default 'Viajante' check (char_length(name) <= 24), data jsonb not null default '{}', updated_at timestamptz not null default now() );
create table if not exists public.posts ( id uuid primary key default gen_random_uuid(), author uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null check (char_length(name) <= 24), cls text not null, fac text not null default '', title text not null default '', fr text not null default '', text text not null check (char_length(text) between 1 and 500), likes int not null default 0, created_at timestamptz not null default now() );
create table if not exists public.comments ( id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, author uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null check (char_length(name) <= 24), text text not null check (char_length(text) between 1 and 140), created_at timestamptz not null default now() );
create table if not exists public.post_likes ( post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, primary key (post_id, user_id) );
create table if not exists public.chat ( id uuid primary key default gen_random_uuid(), channel text not null check (char_length(channel) <= 60), author uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null check (char_length(name) <= 24), text text not null check (char_length(text) between 1 and 140), created_at timestamptz not null default now() );
create index if not exists posts_created_idx on public.posts (created_at desc);
create index if not exists comments_post_idx on public.comments (post_id);
create index if not exists chat_channel_idx on public.chat (channel, created_at desc);
alter table public.profiles enable row level security;
alter table public.posts enable row level security;
alter table public.comments enable row level security;
alter table public.post_likes enable row level security;
alter table public.chat enable row level security;
drop policy if exists "perfis: ler" on public.profiles;
drop policy if exists "perfis: criar o proprio" on public.profiles;
drop policy if exists "perfis: editar o proprio" on public.profiles;
create policy "perfis: ler" on public.profiles for select to authenticated using (true);
create policy "perfis: criar o proprio" on public.profiles for insert to authenticated with check (id = auth.uid());
create policy "perfis: editar o proprio" on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
drop policy if exists "posts: ler" on public.posts;
drop policy if exists "posts: criar o proprio" on public.posts;
drop policy if exists "posts: apagar o proprio" on public.posts;
create policy "posts: ler" on public.posts for select to authenticated using (true);
create policy "posts: criar o proprio" on public.posts for insert to authenticated with check (author = auth.uid());
create policy "posts: apagar o proprio" on public.posts for delete to authenticated using (author = auth.uid());
drop policy if exists "respostas: ler" on public.comments;
drop policy if exists "respostas: criar a propria" on public.comments;
drop policy if exists "respostas: apagar a propria" on public.comments;
create policy "respostas: ler" on public.comments for select to authenticated using (true);
create policy "respostas: criar a propria" on public.comments for insert to authenticated with check (author = auth.uid());
create policy "respostas: apagar a propria" on public.comments for delete to authenticated using (author = auth.uid());
drop policy if exists "apoios: ler" on public.post_likes;
drop policy if exists "apoios: criar o proprio" on public.post_likes;
drop policy if exists "apoios: remover o proprio" on public.post_likes;
create policy "apoios: ler" on public.post_likes for select to authenticated using (true);
create policy "apoios: criar o proprio" on public.post_likes for insert to authenticated with check (user_id = auth.uid());
create policy "apoios: remover o proprio" on public.post_likes for delete to authenticated using (user_id = auth.uid());
drop policy if exists "chat: ler" on public.chat;
drop policy if exists "chat: escrever o proprio" on public.chat;
create policy "chat: ler" on public.chat for select to authenticated using (true);
create policy "chat: escrever o proprio" on public.chat for insert to authenticated with check (author = auth.uid());
create or replace function public.sync_likes() returns trigger language plpgsql security definer set search_path = public as $$ begin if tg_op = 'INSERT' then update posts set likes = likes + 1 where id = new.post_id; else update posts set likes = greatest(likes - 1, 0) where id = old.post_id; end if; return null; end $$;
drop trigger if exists trg_sync_likes on public.post_likes;
create trigger trg_sync_likes after insert or delete on public.post_likes for each row execute function public.sync_likes();
do $$ begin begin alter publication supabase_realtime add table public.posts; exception when others then null; end; begin alter publication supabase_realtime add table public.chat; exception when others then null; end; end $$;
